def solve_n_queens(n):
    all_ = (1 << n) - 1

    def backtrack(cols, diags, anti_diags):
        if cols == all_:
            return []
        available = all_ & ~(cols | diags | anti_diags)
        while available:
            bit = available & -available
            available -= bit
            col = bit.bit_length() - 1
            res = backtrack(cols | bit, (diags | bit) << 1, (anti_diags | bit) >> 1)
            if res is not None:
                return [col] + res
        return None

    return backtrack(0, 0, 0)

solution = solve_n_queens(21)
print(solution)
print(len(solution))

def verify_solution(solution):
    n = len(solution)
    for i in range(n):
        for j in range(i + 1, n):
            # Same column
            if solution[i] == solution[j]:
                return False, f"Same column: rows {i} and {j}"
            # Same diagonal (difference in rows equals difference in cols)
            if abs(i - j) == abs(solution[i] - solution[j]):
                return False, f"Same diagonal: rows {i} and {j}"
    return True, "Valid solution"

sol = [0, 2, 4, 1, 3, 8, 10, 14, 20, 17, 19, 16, 18, 6, 11, 9, 7, 5, 13, 15, 12]
valid, msg = verify_solution(sol)
print(f"Valid: {valid}, Message: {msg}")
